  "classifications": {
    "FRUS278p::Rowan": {
      "label": "1",
      "explanation": "The speaker questions whether the incident can be substantiated and anticipates accusations of fabrication, focusing on the credibility and public legitimacy of the case for action."
    },
    "FRUS119p::Cutler": {
      "label": "0",
      "explanation": "Although it describes geopolitical consequences, the passage centers on atomic deterrence and the strategic effects of the nuclear balance, making it primarily military."
    },
    "DSCN0542_Brown_12-59-5c.rtf": {
      "label": "1",
      "explanation": "The passage interprets the motives and objectives of Soviet political leaders, rather than discussing military operations or capabilities."
    },
    "FRUS225p::Clifford": {
      "label": "1",
      "explanation": "The speaker weighs escalation, moral posture, and the political consequences of appearing to initiate a conflict, even while discussing aircraft readiness."
    },
    "FRUS226p::Mcnamara": {
      "label": "1",
      "explanation": "The passage focuses on diplomatic engagement with Kosygin and on how public belligerence or perceived weakness could affect the political response."
    },
    "FRUS33p::Quarles": {
      "label": "0",
      "explanation": "This is an assessment of blockade risk, island supply levels, and whether U.S. forces could prevent a blockade."
    },
    "FRUS377p::Taylor": {
      "label": "0",
      "explanation": "The passage concerns operational deployment options and the speed with which Marines or an airborne unit could reach Haiti."
    },
    "FRUSB23p::DullesCIA": {
      "label": "0",
      "explanation": "The passage primarily recounts military action, including force sizes, combat, landing cover, and air sorties."
    },
    "FRUS136p.rtf": {
      "label": "1",
      "explanation": "While it discusses an anticipated military attack, the assessment emphasizes political incentives and consequences, including prestige, the home front, and the effects on Chiang's forces."
    },
    "FRUS147p::Rostow": {
      "label": "1",
      "explanation": "The passage focuses on political legitimacy, constitutional government, negotiations, world opinion, and the political impact of bombing."
    }
  },
  "codebook": {
    "definition": "Classify a text as political when its primary concern is political leadership, diplomacy, legitimacy, public opinion, political objectives, or the domestic and international consequences of policy. Classify it as military when its primary concern is forces, weapons, operational capabilities, battlefield events, or military planning.",
    "clarification": "A text can mention military forces or actions and still be political if its central purpose is to assess diplomatic choices, political signaling, legitimacy, or political consequences. Conversely, discussion of geopolitical stakes is not automatically political when the central issue is military capability or deterrence.",
    "positive_examples": [
      {
        "text": "We must be prepared to be accused of fabricating the incident.",
        "explanation": "The concern is the credibility and legitimacy of the account used to justify a response."
      },
      {
        "text": "We are seeking one-man, one-vote constitutional system. We need to turn war to the ballot box.",
        "explanation": "This explicitly concerns political institutions and the pursuit of political legitimacy."
      }
    ],
    "negative_clarification": "Do not classify a text as political merely because it concerns an international conflict or strategic risk. When its main focus is military force levels, operational readiness, weapons, logistics, or combat, classify it as military.",
    "negative_examples": [
      {
        "text": "The Chinese Nationalists had only about 45 days' to two months' supplies on the islands unless they kept them resupplied.",
        "explanation": "This assesses military logistics and the operational vulnerability of the islands."
      },
      {
        "text": "We could put U.S. Marines ashore in Haiti within 51 hours.",
        "explanation": "This describes deployment timing and operational capability."
      }
    ]
  }
}
